import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define TILE_W 16
#define TILE_H 16
#define THREAD_TILE 2
#define OC_TILE 16
#define IC_BLOCK 8
__device__ __forceinline__ void load_ic_block(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* smem_input_ptr,
    float* smem_w_ptr,
    int n, int C_in, int H, int W,
    int C_out, int K,
    int g, int channels_per_group_in,
    int oc_base,
    int ic0, int ic_count,
    int in_x0, int in_y0,
    int in_tile_w, int total_smem_elems,
    int weight_elems,
    int tid, int num_threads)
{
    for (int icb = 0; icb < ic_count; icb++) {
        int in_c = g * channels_per_group_in + ic0 + icb;
        float* smem_ic = smem_input_ptr + icb * total_smem_elems;
        for (int idx = tid; idx < total_smem_elems; idx += num_threads) {
            int sy = idx / in_tile_w;
            int sx = idx % in_tile_w;
            int gy = in_y0 + sy;
            int gx = in_x0 + sx;
            float val = 0.0f;
            if (gy >= 0 && gy < H && gx >= 0 && gx < W) {
                val = input[((n * C_in + in_c) * H + gy) * W + gx];
            }
            smem_ic[idx] = val;
        }
        float* smem_w_ic = smem_w_ptr + icb * weight_elems;
        int ic_global = ic0 + icb;
        for (int idx = tid; idx < weight_elems; idx += num_threads) {
            int o = idx / (K * K);
            int kk = idx % (K * K);
            int oc = oc_base + o;
            float wv = 0.0f;
            if (oc < C_out) {
                const float* w_ptr = weight + ((size_t)oc * channels_per_group_in + ic_global) * K * K;
                wv = w_ptr[kk];
            }
            smem_w_ic[idx] = wv;
        }
    }
}
__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int H, int W,
    int C_out, int K,
    int stride, int padding, int dilation,
    int groups,
    int H_out, int W_out,
    int in_tile_h, int in_tile_w)
{
    extern __shared__ float smem[];
    int tile_w = blockDim.x;
    int tile_h = blockDim.y;
    int out_tile_w = tile_w * THREAD_TILE;
    int out_tile_h = tile_h * THREAD_TILE;
    int out_x0 = blockIdx.x * out_tile_w;
    int out_y0 = blockIdx.y * out_tile_h;
    int num_oc_tiles = (C_out + OC_TILE - 1) / OC_TILE;
    int nc = blockIdx.z;
    int n = nc / num_oc_tiles;
    int oc_tile_idx = nc % num_oc_tiles;
    int oc_base = oc_tile_idx * OC_TILE;
    int channels_per_group_in = C_in / groups;
    int channels_per_group_out = C_out / groups;
    int g = oc_base / channels_per_group_out;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    float acc[OC_TILE][THREAD_TILE][THREAD_TILE];
    #pragma unroll
    for (int o = 0; o < OC_TILE; o++) {
        #pragma unroll
        for (int ry = 0; ry < THREAD_TILE; ry++) {
            #pragma unroll
            for (int rx = 0; rx < THREAD_TILE; rx++) {
                acc[o][ry][rx] = 0.0f;
            }
        }
    }
    int in_x0 = out_x0 * stride - padding;
    int in_y0 = out_y0 * stride - padding;
    int total_smem_elems = in_tile_h * in_tile_w;
    int weight_elems = OC_TILE * K * K;
    int tid = ty * tile_w + tx;
    int num_threads = tile_w * tile_h;
    int buffer_size = IC_BLOCK * (total_smem_elems + weight_elems);
    float* smem_input0 = smem;
    float* smem_w0 = smem + IC_BLOCK * total_smem_elems;
    float* smem_input1 = smem + buffer_size;
    float* smem_w1 = smem + buffer_size + IC_BLOCK * total_smem_elems;
    float* cur_input = smem_input0;
    float* cur_w = smem_w0;
    float* next_input = smem_input1;
    float* next_w = smem_w1;
    int ic0 = 0;
    int cur_ic_count = channels_per_group_in - ic0;
    if (cur_ic_count > IC_BLOCK) cur_ic_count = IC_BLOCK;
    load_ic_block(input, weight, cur_input, cur_w, n, C_in, H, W, C_out, K,
                  g, channels_per_group_in, oc_base, ic0, cur_ic_count,
                  in_x0, in_y0, in_tile_w, total_smem_elems, weight_elems,
                  tid, num_threads);
    __syncthreads();
    for (; ic0 < channels_per_group_in; ic0 += IC_BLOCK) {
        int ic_count = channels_per_group_in - ic0;
        if (ic_count > IC_BLOCK) ic_count = IC_BLOCK;
        int next_ic0 = ic0 + IC_BLOCK;
        if (next_ic0 < channels_per_group_in) {
            int next_ic_count = channels_per_group_in - next_ic0;
            if (next_ic_count > IC_BLOCK) next_ic_count = IC_BLOCK;
            load_ic_block(input, weight, next_input, next_w, n, C_in, H, W, C_out, K,
                          g, channels_per_group_in, oc_base, next_ic0, next_ic_count,
                          in_x0, in_y0, in_tile_w, total_smem_elems, weight_elems,
                          tid, num_threads);
        }
        for (int icb = 0; icb < ic_count; icb++) {
            float* smem_ic = cur_input + icb * total_smem_elems;
            float* smem_w_ic = cur_w + icb * weight_elems;
            #pragma unroll
            for (int ry = 0; ry < THREAD_TILE; ry++) {
                int out_y = out_y0 + ty * THREAD_TILE + ry;
                #pragma unroll
                for (int rx = 0; rx < THREAD_TILE; rx++) {
                    int out_x = out_x0 + tx * THREAD_TILE + rx;
                    if (out_x < W_out && out_y < H_out) {
                        for (int ky = 0; ky < K; ky++) {
                            int sy = (ty * THREAD_TILE + ry) * stride + ky * dilation;
                            const float* smem_row = smem_ic + sy * in_tile_w + (tx * THREAD_TILE + rx) * stride;
                            for (int kx = 0; kx < K; kx++) {
                                float in_val = smem_row[kx * dilation];
                                #pragma unroll
                                for (int o = 0; o < OC_TILE; o++) {
                                    int oc = oc_base + o;
                                    if (oc >= C_out) continue;
                                    float wv = smem_w_ic[o * K * K + ky * K + kx];
                                    acc[o][ry][rx] += in_val * wv;
                                }
                            }
                        }
                    }
                }
            }
        }
        __syncthreads();
        float* tmp_i = cur_input; cur_input = next_input; next_input = tmp_i;
        float* tmp_w = cur_w; cur_w = next_w; next_w = tmp_w;
    }
    #pragma unroll
    for (int o = 0; o < OC_TILE; o++) {
        int oc = oc_base + o;
        if (oc >= C_out) continue;
        #pragma unroll
        for (int ry = 0; ry < THREAD_TILE; ry++) {
            int out_y = out_y0 + ty * THREAD_TILE + ry;
            #pragma unroll
            for (int rx = 0; rx < THREAD_TILE; rx++) {
                int out_x = out_x0 + tx * THREAD_TILE + rx;
                if (out_x < W_out && out_y < H_out) {
                    float val = acc[o][ry][rx];
                    if (bias != nullptr) {
                        val += bias[oc];
                    }
                    output[((n * C_out + oc) * H_out + out_y) * W_out + out_x] = val;
                }
            }
        }
    }
}
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int N = input.size(0);
    int C_in = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int C_out = weight.size(0);
    int K = weight.size(2);
    int H_out = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    int W_out = (W + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    auto output = torch::zeros({N, C_out, H_out, W_out}, input.options());
    dim3 block(TILE_W, TILE_H);
    int out_tile_w = TILE_W * THREAD_TILE;
    int out_tile_h = TILE_H * THREAD_TILE;
    int num_oc_tiles = (C_out + OC_TILE - 1) / OC_TILE;
    dim3 grid(
        (W_out + out_tile_w - 1) / out_tile_w,
        (H_out + out_tile_h - 1) / out_tile_h,
        N * num_oc_tiles
    );
    int in_tile_w = (out_tile_w - 1) * stride + (K - 1) * dilation + 1;
    int in_tile_h = (out_tile_h - 1) * stride + (K - 1) * dilation + 1;
    size_t smem_size = (size_t)2 * IC_BLOCK * ((size_t)in_tile_h * in_tile_w + (size_t)OC_TILE * K * K) * sizeof(float);
    const float* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }
    if (smem_size > 48 * 1024) {
        cudaFuncSetAttribute(conv2d_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_size);
    }
    conv2d_kernel<<<grid, block, smem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, H, W,
        C_out, K,
        stride, padding, dilation,
        groups,
        H_out, W_out,
        in_tile_h, in_tile_w
    );
    return output;
}
"""

conv2d_cpp_source = r"""
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups);
"""

conv2d_module = load_inline(
    name="custom_conv2d",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size)
        )
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
            fan_in = (in_channels // groups) * kernel_size * kernel_size
            bound = 1 / (fan_in ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

        self.conv2d_forward = conv2d_module.conv2d_forward

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()
        bias = self.bias.cuda() if self.bias is not None else torch.tensor([], device=x.device, dtype=x.dtype)

        return self.conv2d_forward(
            x, weight, bias,
            self.stride, self.padding, self.dilation, self.groups
        )


